function Config.UnitData1.data_unit2(slot0)
	if Config.UnitData1.data_unit2_cache[slot0] == nil then
		if not Config.UnitData1.data_unit2_table[slot0] then
			return
		end

		if not loadstring(string.format("return %s", slot1))() then
			return
		end

		Config.UnitData1.data_unit2_cache[slot0] = {
			bid = slot1[1],
			name = slot1[2],
			career = slot1[3],
			camp_type = slot1[4],
			sex = slot1[5],
			lev = slot1[6],
